676		}
677		wg.Wait()
678	
679		// 并发重复停用只能记录一次；待审批只拒绝一次。
680		if countKind(w.Ledger(), LedgerPolicyDeactivation) != 1 {
681			t.Fatal("deactivation recorded more than once")
682		}
683		if countKind(w.Ledger(), LedgerRejection) != 1 {
684			t.Fatal("pending request rejected more than once")
685		}
686		pv, _ := w.Policy("p-approval")
687		if !pv.Deactivated || pv.DeactivateReason != "concurrent stop" {
688			t.Fatalf("policy view = %+v", pv)
689		}
690		// 余额与累计额度无变动。
691		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
692			t.Fatalf("balance = %+v", bal)
693		}
694		if pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
695			t.Fatalf("totals changed: %+v", pv)
696		}
697	}
698	
699	func TestDeactivateDistinguishesLedgerKinds(t *testing.T) {
700		w, _ := setupDeactivate(t)
701		if _, err := w.Apply(approvalApply()); err != nil {
702			t.Fatal(err)
703		}
704		if _, err := w.DeactivatePolicy("p-approval", "sa", "dev-approve", "stop"); err != nil {
705			t.Fatal(err)
706		}
707	
708		// 停用与请求拒绝是两类记录：分别关联出资账户+策略、使用账户+请求。
709		var deact, rej int
710		for _, e := range w.Ledger() {
711			switch e.Kind {
712			case LedgerPolicyDeactivation:
713				deact++
714				if e.AccountID != "payer" || e.PolicyID != "p-approval" || e.RequestID != "" || e.Amount != 0 {
715					t.Fatalf("bad deactivation entry: %+v", e)
716				}
717			case LedgerRejection:
718				rej++
719				if e.AccountID != "u1" || e.PolicyID != "" || e.RequestID != "r1" || e.Amount != 0 {
720					t.Fatalf("bad rejection entry: %+v", e)
721				}
722			}
723		}
724		if deact != 1 || rej != 1 {
725			t.Fatalf("deactivation = %d rejection = %d, want 1/1", deact, rej)
726		}
727		// 按账户查询也能核对：出资账户只见停用，使用账户只见拒绝。
728		if countKind(w.AccountLedger("payer"), LedgerPolicyDeactivation) != 1 ||
729			countKind(w.AccountLedger("payer"), LedgerRejection) != 0 {
730			t.Fatalf("payer ledger = %+v", w.AccountLedger("payer"))
731		}
732		if countKind(w.AccountLedger("u1"), LedgerRejection) != 1 ||
733			countKind(w.AccountLedger("u1"), LedgerPolicyDeactivation) != 0 {
734			t.Fatalf("u1 ledger = %+v", w.AccountLedger("u1"))
735		}
736	}
737	
738	func countKind(entries []LedgerEntry, kind LedgerKind) int {
739		n := 0
740		for _, e := range entries {
741			if e.Kind == kind {
742				n++
743			}
744		}
745		return n
746	}
