772		if led[0].Kind != LedgerPendingApproval || led[1].Kind != LedgerRejection {
773			t.Fatalf("usage ledger kinds = %v, %v", led[0].Kind, led[1].Kind)
774		}
775		// 出资账户账本不含状态留痕。
776		if len(w.AccountLedger("payer")) != 0 {
777			t.Fatalf("payer ledger = %+v, want empty", w.AccountLedger("payer"))
778		}
779	}
780	
781	func TestConcurrentApproveReject(t *testing.T) {
782		w, _ := setupApproval(t)
783		if _, err := w.Apply(approvalApply()); err != nil {
784			t.Fatal(err)
785		}
786	
787		var wg sync.WaitGroup
788		for i := 0; i < 8; i++ {
789			i := i
790			wg.Add(1)
791			go func() {
792				defer wg.Done()
793				if i%2 == 0 {
794					_, _ = w.Approve("u1", "r1", "sa", "dev-approve")
795				} else {
796					_, _ = w.Reject("u1", "r1", "sa", "dev-approve", "concurrent reject")
797				}
798			}()
799		}
800		wg.Wait()
801	
802		// 以账本为准：有且仅有一个决定（批准留痕或拒绝留痕），且只出现一次。
803		approvals, rejections := 0, 0
804		for _, e := range w.Ledger() {
805			switch e.Kind {
806			case LedgerApproval:
807				approvals++
808			case LedgerRejection:
809				rejections++
810			}
811		}
812		if approvals+rejections != 1 {
813			t.Fatalf("decisions = %d (approve %d reject %d), want exactly 1", approvals+rejections, approvals, rejections)
814		}
815		req, _ := w.Request("u1", "r1")
816		if approvals == 1 && req.State != RequestReserved {
817			t.Fatalf("approved but final state = %v", req.State)
818		}
819		if rejections == 1 && req.State != RequestRejected {
820			t.Fatalf("rejected but final state = %v", req.State)
821		}
822		// 余额与状态一致：批准则预留 20，拒绝则不动。
823		bal, _ := w.Balance("payer")
824		if req.State == RequestReserved {
825			if bal != (Balances{Available: 80, Reserved: 20}) {
826				t.Fatalf("balance = %+v, want {80 20}", bal)
827			}
828		} else {
829			if bal != (Balances{Available: 100, Reserved: 0}) {
830				t.Fatalf("balance = %+v, want untouched", bal)
831			}
832		}
833	}
834	
835	func TestConcurrentCancelApprove(t *testing.T) {
836		w, _ := setupApproval(t)
837		if _, err := w.Apply(approvalApply()); err != nil {
838			t.Fatal(err)
839		}
840	
841		var wg sync.WaitGroup
842		wg.Add(2)
843		var cancelErr, approveErr error
844		go func() { defer wg.Done(); _, cancelErr = w.Cancel("u1", "r1") }()
845		go func() { defer wg.Done(); _, approveErr = w.Approve("u1", "r1", "sa", "dev-approve") }()
846		wg.Wait()
847	
848		if cancelErr != nil {
849			t.Fatalf("cancel err = %v", cancelErr)
850		}
851		// 两种合法结局：
852		//  - 取消先完成：批准失败 ErrRequestNotPending，余额不动；
853		//  - 批准先完成：取消按已预留规则退回，余额全额退回。
854		bal, _ := w.Balance("payer")
855		if approveErr == nil {
856			// 批准先完成，随后取消退回全部预留。
857			if bal != (Balances{Available: 100, Reserved: 0}) {
858				t.Fatalf("balance = %+v, want full refund {100 0}", bal)
859			}
860			req, _ := w.Request("u1", "r1")
861			if req.State != RequestCancelled {
862				t.Fatalf("state = %v, want cancelled after approve-then-cancel", req.State)
863			}
864		} else if errors.Is(approveErr, ErrRequestNotPending) {
865			// 取消先完成，批准失败。
866			if bal != (Balances{Available: 100, Reserved: 0}) {
867				t.Fatalf("balance = %+v, want untouched {100 0}", bal)
868			}
869			req, _ := w.Request("u1", "r1")
870			if req.State != RequestCancelled {
871				t.Fatalf("state = %v, want cancelled", req.State)
872			}
873		} else {
874			t.Fatalf("unexpected approve err = %v", approveErr)
875		}
876	}
877	
878	func TestPendingDoesNotOccupySharedQuota(t *testing.T) {
879		w, _ := setupApproval(t)
880		// 多笔待审批不占用共享累计额度：直接预留仍可进行。
881		for i := 0; i < 3; i++ {
882			in := approvalApply()
883			in.RequestID = fmt.Sprintf("p%d", i)
884			if _, err := w.Apply(in); err != nil {
885				t.Fatal(err)
886			}
