888		pv, _ := w.Policy("p-approval")
889		if pv.ReservedTotal != 0 {
890			t.Fatalf("pending occupies quota: reserved %d", pv.ReservedTotal)
891		}
892		// 直接预留一笔（费用等于门槛，不进入待审批）不受待审批影响。
893		reserved := approvalApply()
894		reserved.RequestID = "r-direct"
895		reserved.EstimatedFee = 10
896		if _, err := w.Apply(reserved); err != nil {
897			t.Fatal(err)
898		}
899		pv, _ = w.Policy("p-approval")
900		if pv.ReservedTotal != 10 {
